public static class FoliageBudget19 {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit only");const string A="Assets/ShooterSurvival/Models/Chapters/Chapters45/Ch5Toon20261004";string path=A+"/Native-broad-leaf-pair.asset";if(File.Exists(path))throw new Exception("Already optimized");var v=new List<Vector3>();var tr=new List<int>();foreach(float x in new[]{-8.25f,8.25f})for(int leaf=0;leaf<9;leaf++){float angle=leaf*137.5f*Mathf.Deg2Rad;var radial=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle));var side=Vector3.Cross(Vector3.up,radial);float length=.73f+(leaf%3)*.14f;var stem=new Vector3(x, .92f,6.15f);var tip=stem+radial*(.48f+leaf%2*.10f)+Vector3.up*length;var middle=Vector3.Lerp(stem,tip,.57f)+Vector3.up*.10f;var ridge=middle-radial*.06f;int n=v.Count;v.AddRange(new[]{stem,middle-side*.15f,tip,middle+side*.15f,ridge});tr.AddRange(new[]{n,n+4,n+1,n+1,n+4,n+2,n+2,n+4,n+3,n+3,n+4,n,n+1,n+4,n,n+2,n+4,n+1,n+3,n+4,n+2,n,n+4,n+3});}var mesh=new Mesh{name="Ch5 native broad-leaf pair"};mesh.SetVertices(v);mesh.SetTriangles(tr,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);var material=AssetDatabase.LoadAssetAtPath<Material>(A+"/Leaf green.mat");var root=GameObject.Find("Chapter45_World/DetailedMall_20261003/Scenery").transform;int count=0;long oldTriangles=0;foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){var r=f.GetComponent<Renderer>();if(r==null||!r.enabled||!r.gameObject.activeInHierarchy)continue;string p=AssetDatabase.GetAssetPath(f.sharedMesh);if(!p.StartsWith(A)||!p.Contains("2c03922b57cfd1945a17b2bffbe946fb")||!(p.Contains("/Batch-store")||p.Contains("/Batch-revision2-store-")))continue;oldTriangles+=f.sharedMesh.triangles.Length/3;f.sharedMesh=mesh;r.sharedMaterial=material;count++;}if(count!=56)throw new Exception("Expected 56 facade foliage pairs; got "+count);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());var result=new{pairs=count,plants=count*2,beforeTriangles=oldTriangles,afterTriangles=count*(tr.Count/3),sharedMeshTriangles=tr.Count/3,newNativeMesh=path,retainedOriginalTrellisModel=true,paidGeneration=0};var j=AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert");File.WriteAllText("outputs/ch5-toon-2026-10-04/foliage-optimization.json",(string)j.GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{(object)result}));return result;}}
